import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, PlaneGeometry, SphereGeometry, CylinderGeometry, Mesh, Group } from 'three/webgpu';
import { uv, mix, vec3, vec2, color, smoothstep, sub, lessThan, float } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<{text:string,role:string,typography?:{fontSize?:number}}>} textContent
 * @property {Array<{name:string,params:any,trigger:string}>} cinematicPrimitives
 * @property {string} meshUrl
 * @property {Object} visualSpec
 * @property {Object} visualSpec.colors
 * @property {Array<{at:number,hex:string}>} visualSpec.gradientStops
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} tier
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry } = ctx.THREE;

  const root = new Group();
  root.name = 'OrreryNode';

  // ---------- Backdrop with vertical gradient ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial();
  // vertical gradient using node material
  const uvNode = uv();
  const y = uvNode.y;
  const stop0 = color('#0b0b10');
  const stop1 = color('#101017');
  const stop2 = color('#16161d');
  const gradMid = mix(stop0, stop1, smoothstep(float(0), float(0.65), y));
  const gradient = mix(gradMid, stop2, smoothstep(float(0.65), float(1), y));
  backdropMat.colorNode = gradient;
  backdropMat.transparent = false;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);

  // ---------- Contact shadow ellipse ----------
  const shadowGeom = new PlaneGeometry(7, 6);
  const shadowMat = new MeshStandardNodeMaterial();
  const uvShadow = uv();
  const center = vec2(float(0.5), float(0.5));
  const p = sub(uvShadow, center);
  const ellipse = ((p.x / float(1.3)).pow(2)).add(((p.y / float(0.6)).pow(2)));
  const mask = lessThan(ellipse, float(1));
  const alpha = mix(float(0), float(0.5), mask);
  shadowMat.colorNode = color('#000000');
  shadowMat.alphaNode = alpha;
  shadowMat.transparent = true;
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -1.2, -2.9);
  root.add(shadow);

  // ---------- Load gear mesh ----------
  const gearGroup = new Group();
  root.add(gearGroup);
  const gltfPromise = ctx.glbLoader.loadGLB(config.meshUrl);
  // Synchronous function, but we must ensure resources are loaded before use.
  // The loader returns a promise; we attach then to populate the scene.
  // The returned object will be ready after the promise resolves.
  gltfPromise.then((gltf) => {
    const primaryGear = gltf.scene.clone(true);
    primaryGear.scale.set(1.6 / 2, 1.6 / 2, 1.6 / 2); // normalize to 1.6-unit diameter
    gearGroup.add(primaryGear);

    // secondary gear
    const secondaryGear = gltf.scene.clone(true);
    secondaryGear.scale.set(0.9 / 2, 0.9 / 2, 0.9 / 2);
    secondaryGear.position.set(1.15, 0.35, -0.1);
    gearGroup.add(secondaryGear);

    // rotation animation via GSAP
    const primaryTimeline = gsap.timeline({ repeat: -1 });
    primaryTimeline.to(primaryGear.rotation, { z: '+=6.283185307179586', duration: (2 * Math.PI) / 0.08, ease: 'none' });
    const secondaryTimeline = gsap.timeline({ repeat: -1 });
    secondaryTimeline.to(secondaryGear.rotation, { z: '-=6.283185307179586', duration: (2 * Math.PI) / 0.142, ease: 'none' });

    // store for cleanup
    root.userData._timelines.push(primaryTimeline, secondaryTimeline);
  });

  // ---------- Jewel pivot ----------
  const jewelGeom = new SphereGeometry(0.12, 32, 32);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: '#ff2a38',
    transmission: 0.6,
    ior: 1.76,
    emissive: '#ff2a38',
    emissiveIntensity: 1.8,
    roughness: 0.2,
    metalness: 0,
  });
  const jewel = new Mesh(jewelGeom, jewelMat);
  jewel.position.set(0, 0, 0);
  root.add(jewel);

  // ---------- Arbor shafts ----------
  const shaftGeom = new CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshStandardNodeMaterial({ color: '#16161d' });
  const shaft1 = new Mesh(shaftGeom, shaftMat);
  shaft1.rotation.x = Math.PI / 2;
  root.add(shaft1);
  const shaft2 = shaft1.clone();
  shaft2.position.set(1.15, 0.35, -0.1);
  root.add(shaft2);

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 24,
      color: '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    if (item.role === 'headline') {
      txtObj.position.set(0, -1.7, 0);
    } else {
      txtObj.position.set(0, -2.1, 0);
    }
    root.add(txtObj);
  }

  // ---------- Apply cinematic primitives ----------
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        primitiveInstances.push(instance);
      }
    }
  }

  // ---------- UserData handlers & cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // dispose geometries and materials
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
    // kill GSAP timelines
    if (root.userData._timelines) {
      root.userData._timelines.forEach((tl) => tl.kill());
    }
    // cleanup primitives
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    });
  };
  root.userData._timelines = [];

  return root;
}
